// Generated by vibelang from src/util/presentation.ts; the migrate flow writes it again with each batch.
import { logo } from "../logo";
const reset = "\x1b[0m";
const bold = "\x1b[1m";
const dim = "\x1b[90m";
function wordmark(pad = "") {
    const draw = (line, fg, shadow, bg) => [...line]
        .map((char) => {
        if (char === "_")
            return `${bg} ${reset}`;
        if (char === "^")
            return `${fg}${bg}▀${reset}`;
        if (char === "~")
            return `${shadow}▀${reset}`;
        if (char === " ")
            return " ";
        return `${fg}${char}${reset}`;
    })
        .join("");
    return logo.left.map((line, index) => {
        const left = draw(line, dim, "\x1b[38;5;235m", "\x1b[48;5;235m");
        const right = draw(logo.right[index] ?? "", reset, "\x1b[38;5;238m", "\x1b[48;5;238m");
        return `${pad}${left} ${right}`;
    });
}
// Printed after the TUI closes.
export function epilogue(input) {
    if (!input.session && !input.updatedVersion)
        return;
    const row = (label, value) => `  ${dim}${label.padEnd(10, " ")}${reset}${bold}${value}${reset}`;
    return [
        ...wordmark("  "),
        "",
        ...(input.updatedVersion
            ? [`  ${dim}Run ${reset}${bold}opencode${reset}${dim} to use ${reset}${bold}${input.updatedVersion}${reset}`, ""]
            : []),
        ...(input.session
            ? [row("Session", input.session.title), row("Continue", `opencode -s ${input.session.sessionID}`), ""]
            : []),
    ].join("\n");
}
